    setRows(prev => prev.map(row => (row.id === id ? { ...row, [name]: value } : row)));
  }, []);

  const handleRemoveRow = (id: string) => {
    setRows(prev => {
      const newRows = prev.filter(row => row.id !== id);
      if (newRows.length === 0) {
        return [createNewRow()];
      }
      return newRows;
    });
  };

