          updatedRows.push({ ...createNewRow(), ...pastedRow });
        }
      });
      return updatedRows;
    });
    showSnackbar(`Pasted ${newRowsData.length} rows.`);
  };

  const handleClearAll = () => setRows([createNewRow()]);

  const handleCopyResults = (type: 'flat' | 'gusset') => {
    const text = results
      .map(res => res ? (type === 'flat' ? res.flat : res.gusset) : '')
      .filter(t => t !== '')
      .join('\n');

