  const primaryButtonClasses = "text-white bg-indigo-600 hover:bg-indigo-500 focus:ring-indigo-500";
  const secondaryButtonClasses = "text-gray-300 bg-gray-700 hover:bg-gray-600 focus:ring-gray-500";
  const inputClasses = "block w-full bg-gray-700 border-gray-600 rounded-md shadow-sm text-white focus:ring-indigo-500 focus:border-indigo-500 text-xs sm:text-sm text-center px-1 h-9";
  const selectClasses = "block w-full bg-gray-700 border-gray-600 rounded-md shadow-sm text-white focus:ring-indigo-500 focus:border-indigo-500 text-[10px] sm:text-xs text-center h-9 px-1";
  const headerClasses = "text-[10px] sm:text-xs font-medium text-gray-400 uppercase self-end pb-1 text-center truncate";

  return (
    <div className="max-w-4xl mx-auto space-y-6">
      <div className="bg-gray-800 p-4 sm:p-6 rounded-lg space-y-4 shadow-xl border border-gray-700">
        <div className="flex justify-between items-start border-b border-gray-700 pb-2">
            <h3 className="text-lg font-bold text-indigo-300">Plastic Bag Sizing Calculator</h3>
            <span className="text-[10px] text-gray-500 font-mono">Formula: Opening + Height + Margin</span>
        </div>

        <div className="bg-indigo-900/20 border border-indigo-700/30 p-3 rounded-md mb-2">
            <p className="text-xs sm:text-sm text-indigo-200 leading-relaxed">
                <strong>💡 邏輯補充 (Opening Side Logic):</strong><br/>
                袋口的選擇將直接定義「平口袋寬度」包覆的產品維度：
                <ul className="list-disc ml-5 mt-1 space-y-1">
                  <li><strong>袋口在 W：</strong>平口寬度 = 產品 <strong>W</strong> + H + 預留量。</li>
                  <li><strong>袋口在 L：</strong>平口寬度 = 產品 <strong>L</strong> + H + 預留量。</li>
                </ul>
                袋子長度則會自動包覆剩下的邊長加上產品高度與反摺量。
            </p>
        </div>

        <p className="text-sm text-gray-400 leading-relaxed">
            輸入 L, W, H 尺寸計算規格。平口袋 (Flat Bag) 第一個數值為<strong>包含開口邊與高度</strong>的總袋寬。
        </p>

        <div className="flex flex-wrap items-center gap-4 sm:gap-8 border-b border-gray-700 pb-4">
            <div className="flex items-center gap-2">
                <label className="text-xs text-gray-300 whitespace-nowrap">Margin / 預留 (mm):</label>
                <input 
                    type="number" 
                    value={margin}
                    onChange={(e) => setMargin(e.target.value)}
                    className={`${inputClasses} w-16 h-8`}
                />
            </div>
            <div className="flex items-center gap-2">
                <label className="text-xs text-gray-300 whitespace-nowrap">Fold / 反摺 (mm):</label>
                <input 
                    type="number" 
                    value={foldOverlap}
                    onChange={(e) => setFoldOverlap(e.target.value)}
                    className={`${inputClasses} w-16 h-8`}
                />
            </div>
        </div>

        <div className="flex justify-start pt-1">
          <button onClick={handleAddRow} className={`${buttonBaseClasses} ${secondaryButtonClasses} py-1.5 px-3 text-xs`}>
            Add Row
          </button>
        </div>

        <div className="w-full">
            <div className="grid gap-x-2 gap-y-3 items-center" style={{gridTemplateColumns: 'minmax(40px, 1fr) minmax(40px, 1fr) minmax(40px, 1fr) 100px minmax(70px, 1.2fr) minmax(90px, 1.5fr) 24px'}}>
              <div className={headerClasses} title="Product Length">Prod L</div>
              <div className={headerClasses} title="Product Width">Prod W</div>
              <div className={headerClasses} title="Product Height">Prod H</div>
              <div className={headerClasses}>Opening (袋口)</div>
              <div className={headerClasses}>Flat (WxL)</div>
              <div className={headerClasses}>Gusset (WxLxS)</div>
              <div></div>

              {rows.map((row, index) => (
                <React.Fragment key={row.id}>
                  <input type="number" name="l" value={row.l} onChange={(e) => handleRowChange(row.id, 'l', e.target.value)} onPaste={(e) => handlePaste(e, row.id)} className={inputClasses} placeholder="L" />
                  <input type="number" name="w" value={row.w} onChange={(e) => handleRowChange(row.id, 'w', e.target.value)} onPaste={(e) => handlePaste(e, row.id)} className={inputClasses} placeholder="W" />
                  <input type="number" name="h" value={row.h} onChange={(e) => handleRowChange(row.id, 'h', e.target.value)} onPaste={(e) => handlePaste(e, row.id)} className={inputClasses} placeholder="H" />

                  <select 
                    value={row.openingSide} 
                    onChange={(e) => handleRowChange(row.id, 'openingSide', e.target.value)} 
                    className={selectClasses}
                  >
                    <option value="width">Width (W)</option>
                    <option value="length">Length (L)</option>
                  </select>

                  <div className="bg-gray-900/50 rounded-md text-center p-1 text-[10px] sm:text-xs h-9 flex flex-col items-center justify-center font-mono border border-gray-700/50">
                    <span className="text-green-300">{results[index]?.flat || '-'}</span>
                    {results[index] && (
                        <span className="text-[8px] text-gray-500 uppercase">
                           Open: {row.openingSide === 'width' ? 'W' : 'L'}
                        </span>
                    )}
                  </div>
                  <div className="bg-gray-900/50 rounded-md text-center p-1 text-[10px] sm:text-xs h-9 flex items-center justify-center font-mono text-indigo-300 border border-gray-700/50">
                    {results[index]?.gusset || '-'}
                  </div>
                  <button onClick={() => handleRemoveRow(row.id)} className="text-red-500 hover:text-red-400 flex justify-center transition-colors">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                      <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293 1.293a1 1 0 001.414-1.414L11.414 10l1.293-1.293a1 1 0 00-1.414-1.414L10 8.586 8.707 7.293z" clipRule="evenodd" />
                    </svg>
                  </button>
                </React.Fragment>
              ))}
            </div>
        </div>

        <div className="flex flex-wrap justify-center gap-3 pt-4 border-t border-gray-700">
          <button onClick={() => handleCopyResults('flat')} className={`${buttonBaseClasses} ${primaryButtonClasses} py-1.5 text-xs`}>Copy Flat List</button>
          <button onClick={() => handleCopyResults('gusset')} className={`${buttonBaseClasses} ${primaryButtonClasses} py-1.5 text-xs`}>Copy Gusset List</button>
          <button onClick={handleClearAll} className={`${buttonBaseClasses} ${secondaryButtonClasses} py-1.5 text-xs`}>Clear</button>
