                  >
                    <option value="width">Width (W)</option>
                    <option value="length">Length (L)</option>
                  </select>

                  <div className="bg-gray-900/50 rounded-md text-center p-1 text-xs h-9 flex flex-col items-center justify-center font-mono border border-gray-700/50">
                    <span className="text-green-300">{results[index]?.flat || '-'}</span>
                    {results[index] && (
                        <span className="text-[10px] text-gray-500 uppercase font-sans font-bold">
                           Open: {row.openingSide === 'width' ? 'W' : 'L'}
                        </span>
                    )}
                  </div>
                  <div className="bg-gray-900/50 rounded-md text-center p-1 text-xs h-9 flex items-center justify-center font-mono text-indigo-300 border border-gray-700/50">
                    {results[index]?.gusset || '-'}
                  </div>
                  <button onClick={() => handleRemoveRow(row.id)} className="text-red-500 hover:text-red-400 flex justify-center transition-colors">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                      <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293 1.293a1 1 0 001.414-1.414L11.414 10l1.293-1.293a1 1 0 00-1.414-1.414L10 8.586 8.707 7.293z" clipRule="evenodd" />
                    </svg>
                  </button>
                </React.Fragment>
              ))}
            </div>
        </div>

        <div className="flex flex-wrap justify-center gap-3 pt-4 border-t border-gray-700">
          <button onClick={() => handleCopyResults('flat')} className={`${buttonBaseClasses} ${primaryButtonClasses} py-1.5 text-xs`}>Copy Flat List</button>
          <button onClick={() => handleCopyResults('gusset')} className={`${buttonBaseClasses} ${primaryButtonClasses} py-1.5 text-xs`}>Copy Gusset List</button>
          <button onClick={handleClearAll} className={`${buttonBaseClasses} ${secondaryButtonClasses} py-1.5 text-xs`}>Clear</button>
        </div>
      </div>

      <div role="alert" className={`fixed bottom-5 left-1/2 -translate-x-1/2 px-6 py-3 rounded-lg text-white shadow-lg transition-all duration-300 z-50 ${snackbar.show ? 'translate-y-0 opacity-100' : 'translate-y-20 opacity-0 pointer-events-none'} ${snackbar.type === 'success' ? 'bg-green-600' : 'bg-red-600'}`}>
        {snackbar.message}
      </div>
    </div>
  );
};

export default PlasticSizeCalculator;

import React, { useState, useMemo, useCallback } from 'react';

// --- Types ---
interface ProductRow {
  id: string;
  l: string; // Product Length (mm)
  w: string; // Product Width (mm)
  h: string; // Product Height (mm)
  openingSide: 'width' | 'length'; // Which side is the bag opening at
}

interface SnackbarState {
  show: boolean;
  message: string;
  type: 'success' | 'warning' | 'error';
}

// --- 3D Visualization Helper ---
const ProductDiagram: React.FC<{ row: ProductRow }> = ({ row }) => {
  const l = parseFloat(row.l) || 100;
  const w = parseFloat(row.w) || 60;
  const h = parseFloat(row.h) || 40;

  // Normalize dimensions to fit SVG viewbox (max dimension ~120)
  const maxDim = Math.max(l, w, h);
  const scale = 100 / maxDim;
  const sl = l * scale;
  const sw = w * scale;
  const sh = h * scale;

  // Isometric Projection Math
  // Point order: Bottom Front, Bottom Right, Bottom Back, Bottom Left, Top Front, Top Right, Top Back, Top Left
  const origin = { x: 100, y: 130 };

  // Directions (30 degrees)
  const angle = Math.PI / 6;
  const dxL = Math.cos(angle);
  const dyL = Math.sin(angle);
  const dxW = -Math.cos(angle);
  const dyW = Math.sin(angle);

  const getPoint = (px: number, py: number, pz: number) => ({
    x: origin.x + px * dxL + py * dxW,
    y: origin.y + px * dyL + py * dyW - pz
  });

  const p = [
    getPoint(0, 0, 0),    // 0: Bottom Front
    getPoint(sl, 0, 0),   // 1: Bottom Right
    getPoint(sl, sw, 0),  // 2: Bottom Back
    getPoint(0, sw, 0),   // 3: Bottom Left
    getPoint(0, 0, sh),   // 4: Top Front
    getPoint(sl, 0, sh),  // 5: Top Right
    getPoint(sl, sw, sh), // 6: Top Back
    getPoint(0, sw, sh)   // 7: Top Left
  ];

  const renderPath = (indices: number[], color: string, fill = "none", dash = "") => (
    <path
      d={`M ${p[indices[0]].x} ${p[indices[0]].y} ${indices.slice(1).map(i => `L ${p[i].x} ${p[i].y}`).join(' ')} Z`}
      stroke={color}
      fill={fill}
      strokeWidth="1.5"
      strokeDasharray={dash}
      strokeLinejoin="round"
    />
  );

  return (
    <div className="flex flex-col items-center bg-gray-900/50 rounded-xl p-4 border border-gray-700 relative overflow-hidden group">
      <div className="absolute top-2 left-3 text-[10px] font-bold text-gray-500 uppercase tracking-widest">3D Visualization</div>
      <svg width="200" height="180" viewBox="0 0 200 180" className="drop-shadow-2xl">
        {/* Hidden internal lines */}
        {renderPath([1, 2, 3], "rgba(156, 163, 175, 0.2)", "none", "4 4")}
        {renderPath([2, 6], "rgba(156, 163, 175, 0.2)", "none", "4 4")}

        {/* Product Box Main Faces */}
        {renderPath([0, 1, 5, 4], "#4f46e5", "rgba(79, 70, 229, 0.05)")} {/* Front-Right (L) */}
        {renderPath([0, 3, 7, 4], "#4f46e5", "rgba(79, 70, 229, 0.05)")} {/* Front-Left (W) */}
        {renderPath([4, 5, 6, 7], "#4f46e5", "rgba(79, 70, 229, 0.1)")}  {/* Top (H) */}

        {/* Labels */}
        <text x={p[0].x + (p[1].x - p[0].x)/2 + 10} y={p[0].y + (p[1].y - p[0].y)/2 + 15} fill="#9ca3af" fontSize="10" fontWeight="bold">L</text>
        <text x={p[0].x + (p[3].x - p[0].x)/2 - 15} y={p[0].y + (p[3].y - p[0].y)/2 + 15} fill="#9ca3af" fontSize="10" fontWeight="bold">W</text>
        <text x={p[4].x - 15} y={p[4].y + (p[0].y - p[4].y)/2} fill="#9ca3af" fontSize="10" fontWeight="bold">H</text>

        {/* Bag Opening Indicator */}
        {row.openingSide === 'width' ? (
          // Opening at Width side (W x H plane)
          <g>
            <path
              d={`M ${p[0].x} ${p[0].y} L ${p[3].x} ${p[3].y} L ${p[7].x} ${p[7].y} L ${p[4].x} ${p[4].y} Z`}
              stroke="#22c55e"
              strokeWidth="3"
              fill="rgba(34, 197, 94, 0.2)"
              className="animate-pulse"
            />
            <text x={p[0].x - 40} y={p[0].y - 40} fill="#22c55e" fontSize="10" fontWeight="extrabold">OPENING SIDE</text>
          </g>
        ) : (
          // Opening at Length side (L x H plane)
          <g>
            <path
              d={`M ${p[0].x} ${p[0].y} L ${p[1].x} ${p[1].y} L ${p[5].x} ${p[5].y} L ${p[4].x} ${p[4].y} Z`}
              stroke="#22c55e"
              strokeWidth="3"
              fill="rgba(34, 197, 94, 0.2)"
              className="animate-pulse"
            />
             <text x={p[0].x + 30} y={p[0].y - 40} fill="#22c55e" fontSize="10" fontWeight="extrabold">OPENING SIDE</text>
          </g>
        )}
      </svg>
      <div className="mt-2 text-[10px] text-gray-400 text-center">
        Green plane indicates the <span className="text-green-400 font-bold uppercase underline">Bag Opening</span>
      </div>
    </div>
  );
};

const PlasticSizeCalculator: React.FC = () => {
  const [snackbar, setSnackbar] = useState<SnackbarState>({ show: false, message: '', type: 'success' });
  const [margin, setMargin] = useState('10'); // Default margin in mm
  const [foldOverlap, setFoldOverlap] = useState('30'); // Default fold overlap in mm
  const [activeRowIdx, setActiveRowIdx] = useState(0);

  const createNewRow = (): ProductRow => ({ 
    id: crypto.randomUUID(), 
    l: '', 
    w: '', 
    h: '', 
    openingSide: 'width' 
  });

  const [rows, setRows] = useState<ProductRow[]>([createNewRow()]);

  const showSnackbar = useCallback((message: string, type: 'success' | 'warning' | 'error' = 'success') => {
    setSnackbar({ show: true, message, type });
    setTimeout(() => {
      setSnackbar(prev => ({ ...prev, show: false }));
    }, 3000);
  }, []);

  const results = useMemo(() => {
    const m = parseFloat(margin) || 0;
    const fold = parseFloat(foldOverlap) || 0;

    return rows.map(row => {
      const pl = parseFloat(row.l);
      const pw = parseFloat(row.w);
      const ph = parseFloat(row.h);

      if (isNaN(pl) || isNaN(pw) || isNaN(ph) || pl <= 0 || pw <= 0 || ph <= 0) {
        return null;
      }

      let flatW, flatL, gussetW, gussetL, gussetS;

      if (row.openingSide === 'width') {
        flatW = pw + ph + m;
        flatL = pl + ph + m + fold;

        gussetW = pw + m;
        gussetS = ph + m;
        gussetL = pl + (ph / 2) + m + fold;
      } else {
        flatW = pl + ph + m;
        flatL = pw + ph + m + fold;

        gussetW = pl + m;
        gussetS = ph + m;
        gussetL = pw + (ph / 2) + m + fold;
      }

      return {
        flat: `${Math.ceil(flatW)}x${Math.ceil(flatL)}`,
        gusset: `${Math.ceil(gussetW)}x${Math.ceil(gussetL)}x${Math.ceil(gussetS)}`
      };
    });
  }, [rows, margin, foldOverlap]);

  const handleAddRow = useCallback(() => {
    setRows(prev => [...prev, createNewRow()]);
    setActiveRowIdx(rows.length);
  }, [rows.length]);

  const handleRowChange = useCallback((id: string, name: string, value: string, idx: number) => {
    setRows(prev => prev.map(row => (row.id === id ? { ...row, [name]: value } : row)));
    setActiveRowIdx(idx);
  }, []);

  const handleRemoveRow = (id: string, idx: number) => {
    setRows(prev => {
      const newRows = prev.filter(row => row.id !== id);
      if (newRows.length === 0) {
        setActiveRowIdx(0);
        return [createNewRow()];
      }
      if (idx <= activeRowIdx) setActiveRowIdx(Math.max(0, activeRowIdx - 1));
      return newRows;
    });
  };

  const handlePaste = (e: React.ClipboardEvent<HTMLInputElement>, startRowId: string) => {
    e.preventDefault();
    const pastedText = e.clipboardData.getData('text/plain');
    if (!pastedText || !pastedText.trim()) return;

    const startRowIndex = rows.findIndex(row => row.id === startRowId);
    if (startRowIndex === -1) return;

    const newRowsData = pastedText.trim().split('\n')
      .map(line => {
        const cells = line.split('\t');
        if (cells.length < 3) return null;
        return {
          l: cells[0]?.trim() || '',
          w: cells[1]?.trim() || '',
          h: cells[2]?.trim() || '',
          openingSide: (cells[3]?.trim().toLowerCase() === 'length') ? 'length' : 'width'
        } as ProductRow;
      })
      .filter((row): row is ProductRow => row !== null);

    if (newRowsData.length === 0) {
      showSnackbar('Invalid paste format. Need at least 3 columns (L, W, H).', 'error');
      return;
    }

    setRows(prevRows => {
      const updatedRows = [...prevRows];
      newRowsData.forEach((pastedRow, i) => {
        const targetIndex = startRowIndex + i;
        if (targetIndex < updatedRows.length) {
          updatedRows[targetIndex] = { ...updatedRows[targetIndex], ...pastedRow };
        } else {
          updatedRows.push({ ...pastedRow, id: crypto.randomUUID() });
        }
      });
      return updatedRows;
    });
    showSnackbar(`Pasted ${newRowsData.length} rows.`);
  };

  const handleClearAll = () => {
    setRows([createNewRow()]);
    setActiveRowIdx(0);
  };

  const handleCopyResults = (type: 'flat' | 'gusset') => {
    const text = results
      .map(res => res ? (type === 'flat' ? res.flat : res.gusset) : '')
      .filter(t => t !== '')
      .join('\n');

    if (text) {
      navigator.clipboard.writeText(text).then(() => showSnackbar('Copied!'));
    }
  };

  const buttonBaseClasses = "px-4 py-2 text-sm font-semibold rounded-md transition-all duration-200 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-gray-900";
  const primaryButtonClasses = "text-white bg-indigo-600 hover:bg-indigo-500 focus:ring-indigo-500";
  const secondaryButtonClasses = "text-gray-300 bg-gray-700 hover:bg-gray-600 focus:ring-gray-500";
  const inputClasses = "block w-full bg-gray-700 border-gray-600 rounded-md shadow-sm text-white focus:ring-indigo-500 focus:border-indigo-500 text-xs sm:text-sm text-center px-1 h-9";
  const selectClasses = "block w-full bg-gray-700 border-gray-600 rounded-md shadow-sm text-white focus:ring-indigo-500 focus:border-indigo-500 text-xs text-center h-9 px-1 cursor-pointer";
  const headerClasses = "text-xs font-medium text-gray-400 uppercase self-end pb-1 text-center truncate";

  return (
    <div className="max-w-5xl mx-auto space-y-6">
      <div className="bg-gray-800 p-4 sm:p-6 rounded-2xl space-y-4 shadow-2xl border border-gray-700">
        <div className="flex flex-col md:flex-row gap-6">
          {/* Left: Input Controls */}
          <div className="flex-grow space-y-4">
            <div className="flex justify-between items-start border-b border-gray-700 pb-2">
                <h3 className="text-xl font-bold text-indigo-300">Plastic Bag Sizing</h3>
                <span className="text-xs text-gray-500 font-mono hidden sm:inline">Professional Packaging Utility</span>
            </div>

            <div className="bg-indigo-900/10 border border-indigo-700/30 p-3 rounded-xl">
                <p className="text-xs sm:text-sm text-indigo-200 leading-relaxed">
                    <strong>📐 Packaging Logic Guide:</strong><br/>
                    The <span className="text-green-400 font-bold">Opening Side</span> determines which dimension the bag width (W) will wrap around. 
                    Calculations automatically include the product's height (H) and your custom margins.
                </p>
            </div>

            <div className="flex flex-wrap items-center gap-4 sm:gap-8 border-b border-gray-700 pb-4">
                <div className="flex items-center gap-2">
                    <label className="text-xs text-gray-300 whitespace-nowrap font-medium">Margin (mm):</label>
                    <input 
                        type="number" 
                        value={margin}
                        onChange={(e) => setMargin(e.target.value)}
                        className={`${inputClasses} w-16 h-8 !bg-gray-900`}
                    />
                </div>
                <div className="flex items-center gap-2">
                    <label className="text-xs text-gray-300 whitespace-nowrap font-medium">Fold (mm):</label>
                    <input 
                        type="number" 
                        value={foldOverlap}
                        onChange={(e) => setFoldOverlap(e.target.value)}
                        className={`${inputClasses} w-16 h-8 !bg-gray-900`}
                    />
                </div>
            </div>
          </div>

          {/* Right: 3D Preview (Sticky on desktop) */}
          <div className="md:w-64 flex-shrink-0 self-center">
            <ProductDiagram row={rows[activeRowIdx]} />
          </div>
        </div>

        <div className="flex justify-start pt-1">
          <button onClick={handleAddRow} className={`${buttonBaseClasses} ${secondaryButtonClasses} py-1.5 px-3 text-xs flex items-center gap-1`}>
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 20 20" fill="currentColor">
              <path fillRule="evenodd" d="M10 5a1 1 0 011 1v3h3a1 1 0 110 2h-3v3a1 1 0 11-2 0v-3H6a1 1 0 110-2h3V6a1 1 0 011-1z" clipRule="evenodd" />
            </svg>
            Add Row
          </button>
        </div>

        <div className="w-full overflow-x-auto">
            <div className="grid gap-x-2 gap-y-3 items-center min-w-[700px]" style={{gridTemplateColumns: 'minmax(40px, 1fr) minmax(40px, 1fr) minmax(40px, 1fr) 110px minmax(70px, 1.2fr) minmax(90px, 1.5fr) 24px'}}>
              <div className={headerClasses}>Prod L</div>
              <div className={headerClasses}>Prod W</div>
              <div className={headerClasses}>Prod H</div>
              <div className={headerClasses}>Opening At</div>
              <div className={headerClasses}>Flat (WxL)</div>
              <div className={headerClasses}>Gusset (WxLxS)</div>
              <div></div>

              {rows.map((row, index) => (
                <React.Fragment key={row.id}>
                  <input type="number" name="l" value={row.l} onFocus={() => setActiveRowIdx(index)} onChange={(e) => handleRowChange(row.id, 'l', e.target.value, index)} onPaste={(e) => handlePaste(e, row.id)} className={`${inputClasses} ${activeRowIdx === index ? 'ring-1 ring-indigo-500 border-indigo-500' : ''}`} placeholder="L" />
                  <input type="number" name="w" value={row.w} onFocus={() => setActiveRowIdx(index)} onChange={(e) => handleRowChange(row.id, 'w', e.target.value, index)} onPaste={(e) => handlePaste(e, row.id)} className={`${inputClasses} ${activeRowIdx === index ? 'ring-1 ring-indigo-500 border-indigo-500' : ''}`} placeholder="W" />
                  <input type="number" name="h" value={row.h} onFocus={() => setActiveRowIdx(index)} onChange={(e) => handleRowChange(row.id, 'h', e.target.value, index)} onPaste={(e) => handlePaste(e, row.id)} className={`${inputClasses} ${activeRowIdx === index ? 'ring-1 ring-indigo-500 border-indigo-500' : ''}`} placeholder="H" />

                  <select 
                    value={row.openingSide} 
                    onFocus={() => setActiveRowIdx(index)}
                    onChange={(e) => handleRowChange(row.id, 'openingSide', e.target.value as any, index)} 
                    className={`${selectClasses} ${activeRowIdx === index ? 'ring-1 ring-indigo-500 border-indigo-500' : ''}`}
                  >
                    <option value="width">Width (W)</option>
                    <option value="length">Length (L)</option>
                  </select>

                  <div className={`bg-gray-900/50 rounded-md text-center p-1 text-xs h-9 flex flex-col items-center justify-center font-mono border transition-all ${activeRowIdx === index ? 'border-green-500 shadow-[0_0_10px_rgba(34,197,94,0.15)]' : 'border-gray-700/50'}`}>
                    <span className="text-green-300 font-bold">{results[index]?.flat || '-'}</span>
                    {results[index] && (
                        <span className="text-[10px] text-gray-500 uppercase font-sans font-bold">
                           {row.openingSide === 'width' ? 'W-Open' : 'L-Open'}
                        </span>
                    )}
                  </div>
                  <div className={`bg-gray-900/50 rounded-md text-center p-1 text-xs h-9 flex items-center justify-center font-mono text-indigo-300 border transition-all ${activeRowIdx === index ? 'border-indigo-500' : 'border-gray-700/50'}`}>
                    {results[index]?.gusset || '-'}
                  </div>
                  <button onClick={() => handleRemoveRow(row.id, index)} className="text-red-500 hover:text-red-400 flex justify-center transition-colors">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                      <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293 1.293a1 1 0 001.414-1.414L11.414 10l1.293-1.293a1 1 0 00-1.414-1.414L10 8.586 8.707 7.293z" clipRule="evenodd" />
                    </svg>
                  </button>
                </React.Fragment>
              ))}
            </div>
        </div>

        <div className="flex flex-wrap justify-center gap-3 pt-4 border-t border-gray-700">
          <button onClick={() => handleCopyResults('flat')} className={`${buttonBaseClasses} ${primaryButtonClasses} py-1.5 text-xs flex items-center gap-2`}>
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 5H6a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-1M8 5a2 2 0 002 2h2a2 2 0 002-2M8 5a2 2 0 012-2h2a2 2 0 012 2m0 0h2a2 2 0 012 2v3m2 4H10m0 0l3-3m-3 3l3 3" />
            </svg>
            Copy Flat List
          </button>
          <button onClick={() => handleCopyResults('gusset')} className={`${buttonBaseClasses} ${primaryButtonClasses} py-1.5 text-xs flex items-center gap-2`}>
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 5H6a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-1M8 5a2 2 0 002 2h2a2 2 0 002-2M8 5a2 2 0 012-2h2a2 2 0 012 2m0 0h2a2 2 0 012 2v3m2 4H10m0 0l3-3m-3 3l3 3" />
            </svg>
            Copy Gusset List
          </button>
          <button onClick={handleClearAll} className={`${buttonBaseClasses} ${secondaryButtonClasses} py-1.5 text-xs`}>Clear All</button>
        </div>
      </div>

      <div role="alert" className={`fixed bottom-5 left-1/2 -translate-x-1/2 px-6 py-3 rounded-lg text-white shadow-lg transition-all duration-300 z-50 ${snackbar.show ? 'translate-y-0 opacity-100' : 'translate-y-20 opacity-0 pointer-events-none'} ${snackbar.type === 'success' ? 'bg-green-600' : 'bg-red-600'}`}>
        {snackbar.message}
      </div>
    </div>
  );
};

export default PlasticSizeCalculator;

import React, { useState, useMemo, useCallback } from 'react';

// --- Types ---
interface ProductRow {
  id: string;
  l: string; // Product Length/Depth (mm)
  w: string; // Product Width (mm)
  h: string; // Product Height (mm)
  openingSide: 'width' | 'length'; // Which side is the bag opening at
}

interface SnackbarState {
  show: boolean;
  message: string;
  type: 'success' | 'warning' | 'error';
}

// --- 3D Visualization Helper ---
const ProductDiagram: React.FC<{ row: ProductRow }> = ({ row }) => {
  const l = parseFloat(row.l) || 80;  // Depth (front-back)
  const w = parseFloat(row.w) || 120; // Width (left-right)
  const h = parseFloat(row.h) || 60;  // Height (base-top)

  // Normalize dimensions to fit SVG viewbox
  const maxDim = Math.max(l, w, h);
  const scale = 90 / maxDim;
  const sl = l * scale;
  const sw = w * scale;
  const sh = h * scale;

  // Isometric Projection (W goes right-down, L goes left-down)
  const origin = { x: 100, y: 135 };

  const angle = Math.PI / 6; // 30 degrees
  const dxW = Math.cos(angle);
  const dyW = Math.sin(angle);
  const dxL = -Math.cos(angle);
  const dyL = Math.sin(angle);

  const getPoint = (px: number, py: number, pz: number) => ({
    x: origin.x + px * dxW + py * dxL,
    y: origin.y + px * dyW + py * dyL - pz
  });

  const p = [
    getPoint(0, 0, 0),    // 0: Bottom Front Corner
    getPoint(sw, 0, 0),   // 1: Bottom Right (Width end)
    getPoint(sw, sl, 0),  // 2: Bottom Back (Width & Depth end)
    getPoint(0, sl, 0),   // 3: Bottom Left (Depth end)
    getPoint(0, 0, sh),   // 4: Top Front Corner
    getPoint(sw, 0, sh),  // 5: Top Right
    getPoint(sw, sl, sh), // 6: Top Back
    getPoint(0, sl, sh)   // 7: Top Left
  ];

  const renderPath = (indices: number[], color: string, fill = "none", dash = "", width = "1.5") => (
    <path
      key={indices.join('-')}
      d={`M ${p[indices[0]].x} ${p[indices[0]].y} ${indices.slice(1).map(i => `L ${p[i].x} ${p[i].y}`).join(' ')} Z`}
      stroke={color}
      fill={fill}
      strokeWidth={width}
      strokeDasharray={dash}
      strokeLinejoin="round"
    />
  );

  return (
    <div className="flex flex-col items-center bg-gray-900/50 rounded-xl p-4 border border-gray-700 relative overflow-hidden">
      <div className="absolute top-2 left-3 text-[10px] font-bold text-gray-500 uppercase tracking-widest">3D Preview</div>
      <svg width="200" height="190" viewBox="0 0 200 190" className="drop-shadow-2xl">
        {/* Hidden internal lines */}
        {renderPath([1, 2, 3], "rgba(156, 163, 175, 0.2)", "none", "4 4")}
        {renderPath([2, 6], "rgba(156, 163, 175, 0.2)", "none", "4 4")}

        {/* Product Box Main Faces */}
        {renderPath([0, 1, 5, 4], "#4f46e5", "rgba(79, 70, 229, 0.05)")} {/* Front-Right face (W x H) */}
        {renderPath([0, 3, 7, 4], "#4f46e5", "rgba(79, 70, 229, 0.05)")} {/* Front-Left face (L x H) */}
        {renderPath([4, 5, 6, 7], "#4f46e5", "rgba(79, 70, 229, 0.1)")}  {/* Top face (W x L) */}

        {/* Text "Brand" to help orientation */}
        <text 
            x={(p[0].x + p[1].x) / 2} 
            y={(p[0].y + p[5].y) / 2} 
            fill="rgba(79, 70, 229, 0.3)" 
            fontSize="12" 
            fontWeight="bold" 
            transform={`skewY(30) translate(-30, -50)`}
            className="pointer-events-none select-none"
        >
            BRAND
        </text>

        {/* Dimension Labels based on user image */}
        <text x={p[0].x + (p[1].x - p[0].x)/2 + 5} y={p[0].y + (p[1].y - p[0].y)/2 + 15} fill="#9ca3af" fontSize="10" fontWeight="bold" textAnchor="middle">Width (W)</text>
        <text x={p[0].x + (p[3].x - p[0].x)/2 - 5} y={p[0].y + (p[3].y - p[0].y)/2 + 15} fill="#9ca3af" fontSize="10" fontWeight="bold" textAnchor="middle">Depth (L)</text>
        <text x={p[1].x + 10} y={p[1].y + (p[5].y - p[1].y)/2} fill="#9ca3af" fontSize="10" fontWeight="bold">Height (H)</text>

        {/* Bag Opening Indicator */}
        {row.openingSide === 'width' ? (
          // Opening at Width side (The W x H face)
          <g>
            {renderPath([0, 1, 5, 4], "#22c55e", "rgba(34, 197, 94, 0.2)", "", "3")}
            <text x={p[5].x} y={p[5].y - 10} fill="#22c55e" fontSize="10" fontWeight="extrabold" textAnchor="middle" className="animate-pulse">OPENING (W)</text>
          </g>
        ) : (
          // Opening at Length side (The L x H face)
          <g>
            {renderPath([0, 3, 7, 4], "#22c55e", "rgba(34, 197, 94, 0.2)", "", "3")}
            <text x={p[7].x} y={p[7].y - 10} fill="#22c55e" fontSize="10" fontWeight="extrabold" textAnchor="middle" className="animate-pulse">OPENING (L)</text>
          </g>
        )}
      </svg>
      <div className="mt-2 text-[10px] text-gray-400 text-center leading-tight">
        <span className="text-green-400 font-bold uppercase underline">Green face</span> shows where the bag <br/> slides onto the product.
      </div>
    </div>
  );
};

const PlasticSizeCalculator: React.FC = () => {
  const [snackbar, setSnackbar] = useState<SnackbarState>({ show: false, message: '', type: 'success' });
  const [margin, setMargin] = useState('10'); // Default margin in mm
  const [foldOverlap, setFoldOverlap] = useState('30'); // Default fold overlap in mm
  const [activeRowIdx, setActiveRowIdx] = useState(0);

  const createNewRow = (): ProductRow => ({ 
    id: crypto.randomUUID(), 
    l: '', // Depth
    w: '', // Width
    h: '', // Height
    openingSide: 'width' 
  });

  const [rows, setRows] = useState<ProductRow[]>([createNewRow()]);

  const showSnackbar = useCallback((message: string, type: 'success' | 'warning' | 'error' = 'success') => {
    setSnackbar({ show: true, message, type });
    setTimeout(() => {
      setSnackbar(prev => ({ ...prev, show: false }));
    }, 3000);
  }, []);

  const results = useMemo(() => {
    const m = parseFloat(margin) || 0;
    const fold = parseFloat(foldOverlap) || 0;

    return rows.map(row => {
      const pl = parseFloat(row.l);
      const pw = parseFloat(row.w);
      const ph = parseFloat(row.h);

      if (isNaN(pl) || isNaN(pw) || isNaN(ph) || pl <= 0 || pw <= 0 || ph <= 0) {
        return null;
      }

      let flatW, flatL, gussetW, gussetL, gussetS;

      if (row.openingSide === 'width') {
        // Bag opening is the Width face (Wraps Width + Height)
        flatW = pw + ph + m;
        flatL = pl + ph + m + fold;

        gussetW = pw + m;
        gussetS = ph + m;
        gussetL = pl + (ph / 2) + m + fold;
      } else {
        // Bag opening is the Length/Depth face (Wraps Length + Height)
        flatW = pl + ph + m;
        flatL = pw + ph + m + fold;

        gussetW = pl + m;
        gussetS = ph + m;
        gussetL = pw + (ph / 2) + m + fold;
      }

      return {
        flat: `${Math.ceil(flatW)}x${Math.ceil(flatL)}`,
        gusset: `${Math.ceil(gussetW)}x${Math.ceil(gussetL)}x${Math.ceil(gussetS)}`
      };
    });
  }, [rows, margin, foldOverlap]);

  const handleAddRow = useCallback(() => {
    setRows(prev => [...prev, createNewRow()]);
    setActiveRowIdx(rows.length);
  }, [rows.length]);

  const handleRowChange = useCallback((id: string, name: string, value: string, idx: number) => {
    setRows(prev => prev.map(row => (row.id === id ? { ...row, [name]: value } : row)));
    setActiveRowIdx(idx);
  }, []);

  const handleRemoveRow = (id: string, idx: number) => {
    setRows(prev => {
      const newRows = prev.filter(row => row.id !== id);
      if (newRows.length === 0) {
        setActiveRowIdx(0);
        return [createNewRow()];
      }
      if (idx <= activeRowIdx) setActiveRowIdx(Math.max(0, activeRowIdx - 1));
      return newRows;
    });
  };

  const handlePaste = (e: React.ClipboardEvent<HTMLInputElement>, startRowId: string) => {
    e.preventDefault();
    const pastedText = e.clipboardData.getData('text/plain');
    if (!pastedText || !pastedText.trim()) return;

    const startRowIndex = rows.findIndex(row => row.id === startRowId);
    if (startRowIndex === -1) return;

    const newRowsData = pastedText.trim().split('\n')
      .map(line => {
        const cells = line.split('\t');
        if (cells.length < 3) return null;
        // Expected pasted order: W, L, H or just map based on your column UI
        return {
          w: cells[0]?.trim() || '',
          l: cells[1]?.trim() || '',
          h: cells[2]?.trim() || '',
          openingSide: (cells[3]?.trim().toLowerCase() === 'length' || cells[3]?.trim().toLowerCase() === 'depth') ? 'length' : 'width'
        } as ProductRow;
      })
      .filter((row): row is ProductRow => row !== null);

    if (newRowsData.length === 0) {
      showSnackbar('Invalid paste format. Need 3-4 columns (Width, Depth, Height, [Opening]).', 'error');
      return;
    }

    setRows(prevRows => {
      const updatedRows = [...prevRows];
      newRowsData.forEach((pastedRow, i) => {
        const targetIndex = startRowIndex + i;
        if (targetIndex < updatedRows.length) {
          updatedRows[targetIndex] = { ...updatedRows[targetIndex], ...pastedRow };
        } else {
          updatedRows.push({ ...pastedRow, id: crypto.randomUUID() });
        }
      });
      return updatedRows;
    });
    showSnackbar(`Pasted ${newRowsData.length} rows.`);
  };

  const handleClearAll = () => {
    setRows([createNewRow()]);
    setActiveRowIdx(0);
  };

  const handleCopyResults = (type: 'flat' | 'gusset') => {
    const text = results
      .map(res => res ? (type === 'flat' ? res.flat : res.gusset) : '')
      .filter(t => t !== '')
      .join('\n');

    if (text) {
      navigator.clipboard.writeText(text).then(() => showSnackbar('Copied!'));
    }
  };

  const buttonBaseClasses = "px-4 py-2 text-sm font-semibold rounded-md transition-all duration-200 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-gray-900";
  const primaryButtonClasses = "text-white bg-indigo-600 hover:bg-indigo-500 focus:ring-indigo-500";
  const secondaryButtonClasses = "text-gray-300 bg-gray-700 hover:bg-gray-600 focus:ring-gray-500";
  const inputClasses = "block w-full bg-gray-700 border-gray-600 rounded-md shadow-sm text-white focus:ring-indigo-500 focus:border-indigo-500 text-xs sm:text-sm text-center px-1 h-9";
  const selectClasses = "block w-full bg-gray-700 border-gray-600 rounded-md shadow-sm text-white focus:ring-indigo-500 focus:border-indigo-500 text-xs text-center h-9 px-1 cursor-pointer";
  const headerClasses = "text-xs font-bold text-gray-400 uppercase self-end pb-1 text-center truncate";

  return (
    <div className="max-w-5xl mx-auto space-y-6">
      <div className="bg-gray-800 p-4 sm:p-6 rounded-2xl space-y-4 shadow-2xl border border-gray-700">
        <div className="flex flex-col md:flex-row gap-6">
          {/* Left: Input Controls */}
          <div className="flex-grow space-y-4">
            <div className="flex justify-between items-start border-b border-gray-700 pb-2">
                <h3 className="text-xl font-bold text-indigo-300">Plastic Bag Sizing Calculator</h3>
                <span className="text-xs text-gray-500 font-mono hidden sm:inline">Industrial Standard</span>
            </div>

            <div className="bg-indigo-900/10 border border-indigo-700/30 p-3 rounded-xl">
                <p className="text-xs sm:text-sm text-indigo-200 leading-relaxed">
                    <strong>📍 Dimension Definition (尺寸定義):</strong><br/>
                    • <b>Width (W):</b> Left to right dimension.<br/>
                    • <b>Depth (L):</b> Front to back dimension.<br/>
                    • <b>Height (H):</b> Base to top dimension.
                </p>
            </div>

            <div className="flex flex-wrap items-center gap-4 sm:gap-8 border-b border-gray-700 pb-4">
                <div className="flex items-center gap-2">
                    <label className="text-xs text-gray-300 whitespace-nowrap font-medium">Margin (mm):</label>
                    <input 
                        type="number" 
                        value={margin}
                        onChange={(e) => setMargin(e.target.value)}
                        className={`${inputClasses} w-16 h-8 !bg-gray-900`}
                    />
                </div>
                <div className="flex items-center gap-2">
                    <label className="text-xs text-gray-300 whitespace-nowrap font-medium">Fold Overlap (mm):</label>
                    <input 
                        type="number" 
                        value={foldOverlap}
                        onChange={(e) => setFoldOverlap(e.target.value)}
                        className={`${inputClasses} w-16 h-8 !bg-gray-900`}
                    />
                </div>
            </div>
          </div>

          {/* Right: 3D Preview */}
          <div className="md:w-64 flex-shrink-0 self-center">
            <ProductDiagram row={rows[activeRowIdx]} />
          </div>
        </div>

        <div className="flex justify-start pt-1">
          <button onClick={handleAddRow} className={`${buttonBaseClasses} ${secondaryButtonClasses} py-1.5 px-3 text-xs flex items-center gap-1`}>
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 20 20" fill="currentColor">
              <path fillRule="evenodd" d="M10 5a1 1 0 011 1v3h3a1 1 0 110 2h-3v3a1 1 0 11-2 0v-3H6a1 1 0 110-2h3V6a1 1 0 011-1z" clipRule="evenodd" />
            </svg>
            Add Row
          </button>
        </div>

        <div className="w-full overflow-x-auto">
            <div className="grid gap-x-2 gap-y-3 items-center min-w-[700px]" style={{gridTemplateColumns: 'minmax(40px, 1fr) minmax(40px, 1fr) minmax(40px, 1fr) 120px minmax(70px, 1.2fr) minmax(90px, 1.5fr) 24px'}}>
              <div className={headerClasses} title="Width (Left-Right)">Width (W)</div>
              <div className={headerClasses} title="Depth (Front-Back)">Depth (L)</div>
              <div className={headerClasses} title="Height (Base-Top)">Height (H)</div>
              <div className={headerClasses}>Opening Side</div>
              <div className={headerClasses}>Flat (WxL)</div>
              <div className={headerClasses}>Gusset (WxLxS)</div>
              <div></div>

              {rows.map((row, index) => (
                <React.Fragment key={row.id}>
                  <input type="number" name="w" value={row.w} onFocus={() => setActiveRowIdx(index)} onChange={(e) => handleRowChange(row.id, 'w', e.target.value, index)} onPaste={(e) => handlePaste(e, row.id)} className={`${inputClasses} ${activeRowIdx === index ? 'ring-2 ring-indigo-500 border-indigo-500' : ''}`} placeholder="W" />
                  <input type="number" name="l" value={row.l} onFocus={() => setActiveRowIdx(index)} onChange={(e) => handleRowChange(row.id, 'l', e.target.value, index)} onPaste={(e) => handlePaste(e, row.id)} className={`${inputClasses} ${activeRowIdx === index ? 'ring-2 ring-indigo-500 border-indigo-500' : ''}`} placeholder="L" />
                  <input type="number" name="h" value={row.h} onFocus={() => setActiveRowIdx(index)} onChange={(e) => handleRowChange(row.id, 'h', e.target.value, index)} onPaste={(e) => handlePaste(e, row.id)} className={`${inputClasses} ${activeRowIdx === index ? 'ring-2 ring-indigo-500 border-indigo-500' : ''}`} placeholder="H" />

                  <select 
                    value={row.openingSide} 
                    onFocus={() => setActiveRowIdx(index)}
                    onChange={(e) => handleRowChange(row.id, 'openingSide', e.target.value as any, index)} 
                    className={`${selectClasses} ${activeRowIdx === index ? 'ring-2 ring-indigo-500 border-indigo-500' : ''}`}
                  >
                    <option value="width">Width (W)</option>
                    <option value="length">Depth (L)</option>
                  </select>

                  <div className={`bg-gray-900/50 rounded-md text-center p-1 text-xs h-9 flex flex-col items-center justify-center font-mono border transition-all ${activeRowIdx === index ? 'border-green-500 shadow-[0_0_10px_rgba(34,197,94,0.15)]' : 'border-gray-700/50'}`}>
                    <span className="text-green-300 font-bold">{results[index]?.flat || '-'}</span>
                    {results[index] && (
                        <span className="text-[10px] text-gray-500 uppercase font-sans font-bold">
                           {row.openingSide === 'width' ? 'W-Open' : 'L-Open'}
                        </span>
                    )}
                  </div>
                  <div className={`bg-gray-900/50 rounded-md text-center p-1 text-xs h-9 flex items-center justify-center font-mono text-indigo-300 border transition-all ${activeRowIdx === index ? 'border-indigo-500' : 'border-gray-700/50'}`}>
                    {results[index]?.gusset || '-'}
                  </div>
                  <button onClick={() => handleRemoveRow(row.id, index)} className="text-red-500 hover:text-red-400 flex justify-center transition-colors">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                      <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293 1.293a1 1 0 001.414-1.414L11.414 10l1.293-1.293a1 1 0 00-1.414-1.414L10 8.586 8.707 7.293z" clipRule="evenodd" />
                    </svg>
                  </button>
                </React.Fragment>
              ))}
            </div>
        </div>

        <div className="flex flex-wrap justify-center gap-3 pt-4 border-t border-gray-700">
          <button onClick={() => handleCopyResults('flat')} className={`${buttonBaseClasses} ${primaryButtonClasses} py-1.5 text-xs flex items-center gap-2`}>
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 5H6a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-1M8 5a2 2 0 002 2h2a2 2 0 002-2M8 5a2 2 0 012-2h2a2 2 0 012 2m0 0h2a2 2 0 012 2v3m2 4H10m0 0l3-3m-3 3l3 3" />
            </svg>
            Copy Flat List
          </button>
          <button onClick={() => handleCopyResults('gusset')} className={`${buttonBaseClasses} ${primaryButtonClasses} py-1.5 text-xs flex items-center gap-2`}>
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 5H6a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-1M8 5a2 2 0 002 2h2a2 2 0 002-2M8 5a2 2 0 012-2h2a2 2 0 012 2m0 0h2a2 2 0 012 2v3m2 4H10m0 0l3-3m-3 3l3 3" />
            </svg>
            Copy Gusset List
          </button>
          <button onClick={handleClearAll} className={`${buttonBaseClasses} ${secondaryButtonClasses} py-1.5 text-xs`}>Clear All</button>
        </div>
      </div>

      <div role="alert" className={`fixed bottom-5 left-1/2 -translate-x-1/2 px-6 py-3 rounded-lg text-white shadow-lg transition-all duration-300 z-50 ${snackbar.show ? 'translate-y-0 opacity-100' : 'translate-y-20 opacity-0 pointer-events-none'} ${snackbar.type === 'success' ? 'bg-green-600' : 'bg-red-600'}`}>
        {snackbar.message}
      </div>
    </div>
  );
};

