          <button onClick={handleClearAll} className={`${buttonBaseClasses} ${secondaryButtonClasses} py-1.5 text-xs`}>Clear All</button>
        </div>
      </div>

      <div role="alert" className={`fixed bottom-5 left-1/2 -translate-x-1/2 px-6 py-3 rounded-lg text-white shadow-lg transition-all duration-300 z-50 ${snackbar.show ? 'translate-y-0 opacity-100' : 'translate-y-20 opacity-0 pointer-events-none'} ${snackbar.type === 'success' ? 'bg-green-600' : 'bg-red-600'}`}>
        {snackbar.message}
      </div>
    </div>
  );
};

